using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAI.OpenAIClient(apiKey)));

builder.Services.AddSingleton<NoteStore>();
builder.Services.AddSingleton<WebSearchTool>();
builder.Services.AddSingleton<NoteTool>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var noteStore = host.Services.GetRequiredService<NoteStore>();
var webSearchTool = host.Services.GetRequiredService<WebSearchTool>();
var noteTool = host.Services.GetRequiredService<NoteTool>();

var agent = new ChatClientAgent(chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about the topic. " +
    "Use the add_note tool to save important findings. " +
    "After gathering enough information (at least 3 searches), " +
    "use the get_notes tool to review your notes and provide a comprehensive summary.")
{
    Tools = [webSearchTool.SearchWeb, noteTool.AddNote, noteTool.GetNotes],
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User,
        $"Research the following topic thoroughly: \"{topic}\". " +
        "Search for key facts, recent developments, and different perspectives. " +
        "Take notes on important findings, then provide a final summary.")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Research Complete ===");
Console.WriteLine($"Notes collected: {noteStore.Notes.Count}");
foreach (var note in noteStore.Notes)
{
    Console.WriteLine($"  • {note}");
}

