namespace ResearchAgent.Tools;

/// <summary>
/// Provides a simulated web search tool for the research agent.
/// In production, replace the body with a real search API (Bing, Google, etc.).
/// </summary>
public sealed class WebSearchTool
{
    [Description("Search the web for information on a given query. Returns a list of search results with titles and snippets.")]
    [AIFunction(Name = "web_search")]
    public static string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated search results — replace with a real search API integration
        // (e.g., Bing Web Search API, Google Custom Search) for production use.
        return $"""
            Search results for: "{query}"

            1. [Wikipedia] Overview of {query}
               Snippet: {query} is a broad topic with many facets. Recent research has shown significant developments in this area, with multiple perspectives from academics and practitioners.

            2. [Research Journal] Recent Advances in {query}
               Snippet: A 2024 study found that {query} has evolved significantly over the past decade. Key trends include increased adoption, new methodologies, and growing interdisciplinary interest.

            3. [News] Latest Developments in {query}
               Snippet: Industry experts predict major changes in {query} over the coming years. New technologies and frameworks are reshaping how practitioners approach this field.

            4. [Academic Paper] Critical Analysis of {query}
               Snippet: This paper examines the challenges and opportunities in {query}, highlighting both the potential benefits and the risks that need to be managed carefully.
            """;
    }
}

using System.ComponentModel;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

/// <summary>
/// Provides note-taking tools for the research agent to save and retrieve findings.
/// </summary>
public sealed class NoteTool(NoteStore store)
{
    [Description("Save an important finding or observation as a note for later reference.")]
    [AIFunction(Name = "add_note")]
    public string AddNote(
        [Description("The content of the note to save")] string content)
    {
        store.Add(content);
        return $"Note saved. Total notes: {store.Notes.Count}";
    }

    [Description("Retrieve all saved notes to review findings before writing a summary.")]
    [AIFunction(Name = "get_notes")]
    public string GetNotes()
    {
        return store.GetAll();
    }
}

